(function(){'use strict';function initContentFeedback(){const memeImages=document.querySelectorAll('.meme-image,img[data-meme-url]');memeImages.forEach(img=>{img.addEventListener('error',function(){showFeedbackButton(this);});if(img.complete && img.naturalHeight===0){showFeedbackButton(img);}});}function showFeedbackButton(img){if(img.dataset.feedbackAdded)return;img.dataset.feedbackAdded='true';const button=document.createElement('button');button.className='content-feedback-btn';button.innerHTML='🚫 Report Issue';button.title='Help us improve by reporting this broken content';Object.assign(button.style,{position:'absolute',bottom:'10px',right:'10px',padding:'8px 16px',background:'rgba(255,59,48,0.9)',color:'white',border:'none',borderRadius:'6px',cursor:'pointer',fontSize:'14px',fontWeight:'600',zIndex:'1000',boxShadow:'0 2px 8px rgba(0,0,0,0.3)',transition:'all 0.2s ease'});button.addEventListener('mouseenter',()=>{button.style.background='rgba(255,59,48,1)';button.style.transform='scale(1.05)';});button.addEventListener('mouseleave',()=>{button.style.background='rgba(255,59,48,0.9)';button.style.transform='scale(1)';});button.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();reportBrokenContent(img,button);});const container=img.parentElement;if(container){container.style.position='relative';container.appendChild(button);}}function reportBrokenContent(img,button){const url=img.src || img.dataset.memeUrl;if(!url){showFeedback(button,'⚠️ No URL found','warning');return;}button.disabled=true;button.innerHTML='⏳ Reporting...';fetch('/api/report-broken-content',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':getCsrfToken()},body:JSON.stringify({url:url,page:window.location.pathname,user_agent:navigator.userAgent})}).then(response=> response.json()).then(data=>{if(data.success){showFeedback(button,'✅ Reported','success');setTimeout(()=>{button.style.opacity='0';setTimeout(()=> button.remove(),300);},2000);}else{showFeedback(button,'❌ Failed','error');}}).catch(error=>{console.error('Report error:',error);showFeedback(button,'❌ Error','error');});}function showFeedback(button,message,type){button.innerHTML=message;if(type==='success'){button.style.background='rgba(52,199,89,0.9)';}else if(type==='error' || type==='warning'){button.style.background='rgba(255,149,0,0.9)';}if(type !=='success'){setTimeout(()=>{button.disabled=false;button.innerHTML='🚫 Report Issue';button.style.background='rgba(255,59,48,0.9)';},3000);}}function getCsrfToken(){const meta=document.querySelector('meta[name="csrf-token"]');if(meta)return meta.content;const match=document.cookie.match(/csrf_token=([^;]+)/);return match ? match[1]:'';}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initContentFeedback);}else{initContentFeedback();}window.addEventListener('load',initContentFeedback);})();